# More famous Welsh people, part A: from Rome to the Stuarts.
# House voice (EDITORIAL.md): proud, nothing negative about Welsh figures, contested points in the
# tradition's own words. people2.py gathers parts A, B and C and data.py / long.py pull them in.
# Each entry: P(slug, era, dates, nameEn, nameCy, epithetEn, epithetCy, wikipediaTitle, field,
#               bioEn, bioCy, [long paragraphs EN], [long paragraphs CY], first=(kind, en, cy, year) or None)


def P(*a, first=None):
    return dict(zip(("id", "era", "d", "en", "cy", "eEn", "eCy", "w", "f", "bEn", "bCy", "lEn", "lCy"), a), first=first)


PEOPLE = [
 P("macsen-wledig", "roman", "d. 388", "Magnus Maximus", "Macsen Wledig", "Emperor from Britain", "Ymerawdwr o Brydain", "Magnus_Maximus", "rulers",
   "Commander of the army in Britain who was raised to emperor in 383 and ruled the West. Wales remembers him as Macsen Wledig, forefather of its kings.",
   "Cadlywydd y fyddin ym Mhrydain a godwyd yn ymerawdwr yn 383 ac a reolodd y Gorllewin. Mae Cymru’n ei gofio fel Macsen Wledig, cyndad ei brenhinoedd.",
   ["In 383 the soldiers of Britain proclaimed their general, Magnus Maximus, emperor of Rome. He crossed to Gaul with the fighting men of the island behind him and for five years ruled Britain, Gaul and Spain from Trier.",
    "Welsh tradition made him its own. As Macsen Wledig he heads the royal pedigrees of Gwynedd, Powys and Gwent, and the Pillar of Eliseg names him as forefather of the house of Powys. The tale Breuddwyd Macsen tells how he dreamed of Elen of Caernarfon and made her his empress, and Welsh tradition holds that the men who followed him settled in Armorica and founded Brittany. Dafydd Iwan’s Yma o Hyd begins with him."],
   ["Yn 383 cyhoeddodd milwyr Prydain eu cadfridog, Magnus Maximus, yn ymerawdwr Rhufain. Croesodd i Âl â rhyfelwyr yr ynys y tu ôl iddo, ac am bum mlynedd rheolodd Brydain, Gâl a Sbaen o Trier.",
    "Gwnaeth traddodiad Cymru ef yn eiddo iddi hi ei hun. Fel Macsen Wledig saif ar ben achau brenhinol Gwynedd, Powys a Gwent, ac mae Piler Eliseg yn ei enwi’n gyndad tŷ Powys. Mae chwedl Breuddwyd Macsen yn adrodd sut y breuddwydiodd am Elen o Gaernarfon a’i gwneud yn ymerodres, ac yn ôl traddodiad Cymru ymsefydlodd ei wŷr yn Armorica a sefydlu Llydaw. Ag ef y mae Yma o Hyd Dafydd Iwan yn dechrau."]),
 P("elen-luyddog", "roman", "fl. late 4th century", "Elen of the Hosts", "Elen Luyddog", "Empress and road builder", "Ymerodres ac adeiladydd ffyrdd", "Elen_of_the_Hosts", "rulers",
   "The British empress of Macsen Wledig. Welsh tradition credits her with the great roads of Wales, still called Sarn Helen.",
   "Ymerodres Frythonig Macsen Wledig. Yn ôl traddodiad Cymru hi a gododd ffyrdd mawr Cymru, a elwir yn Sarn Helen hyd heddiw.",
   ["In the Welsh tale Breuddwyd Macsen, the emperor dreams of a maiden in a fort at the mouth of the Seiont. His messengers find her at Caernarfon, and Elen, daughter of Eudaf, becomes his empress.",
    "She asked for roads to be built from fort to fort across Britain so that her people could move freely, and the old Roman roads that run the length of Wales are still called Sarn Helen, Elen’s causeway. Welsh tradition counts her among the saints, and churches in north Wales bear her name."],
   ["Yn chwedl Breuddwyd Macsen mae’r ymerawdwr yn breuddwydio am forwyn mewn caer wrth aber afon Seiont. Mae ei negeswyr yn ei chael yng Nghaernarfon, a daw Elen, merch Eudaf, yn ymerodres iddo.",
    "Gofynnodd am ffyrdd o gaer i gaer ar draws Prydain er mwyn i’w phobl gael teithio’n rhydd, a gelwir yr hen ffyrdd Rhufeinig sy’n rhedeg drwy hyd Cymru yn Sarn Helen hyd heddiw. Mae traddodiad Cymru’n ei chyfrif ymhlith y saint, ac mae eglwysi yn y gogledd yn dwyn ei henw."]),
 P("pelagius", "roman", "c. 354–c. 418", "Pelagius", "Pelagius", "The first British writer", "Yr awdur Brythonig cyntaf", "Pelagius", "faith",
   "A Briton who became one of the most famous thinkers in Rome. He taught that every person is free to choose good, and is the first writer from Britain whose works survive.",
   "Brython a ddaeth yn un o feddylwyr enwocaf Rhufain. Dysgodd fod pob person yn rhydd i ddewis daioni, a’i waith ef yw’r gwaith cynharaf gan awdur o Brydain sydd wedi goroesi.",
   ["Pelagius was born in Britain in the middle of the fourth century and travelled to Rome, where his learning and his strict, generous life won him a wide following. He wrote commentaries on the letters of Saint Paul and letters of advice that were copied for centuries.",
    "His great idea was human freedom: that God made people able to choose good, and that they are answerable for their choices. It led him into a famous debate with Augustine of Hippo. Later Welsh writers claimed him as a son of Wales, and his books are the earliest surviving works by any writer from Britain."],
   ["Ganed Pelagius ym Mhrydain ganol y bedwaredd ganrif a theithiodd i Rufain, lle enillodd ei ddysg a’i fywyd llym a hael ddilynwyr lawer. Ysgrifennodd esboniadau ar epistolau Paul a llythyrau o gyngor a gopïwyd am ganrifoedd.",
    "Ei syniad mawr oedd rhyddid dyn: i Dduw greu pobl yn abl i ddewis daioni, a’u bod yn atebol am eu dewisiadau. Arweiniodd hynny at ddadl enwog ag Awstin o Hippo. Hawliodd awduron Cymreig diweddarach ef yn fab i Gymru, a’i lyfrau ef yw’r gweithiau cynharaf sydd wedi goroesi gan unrhyw awdur o Brydain."],
   first=("world", "The earliest surviving books by a writer from Britain", "Y llyfrau cynharaf sydd wedi goroesi gan awdur o Brydain", 410)),
 P("cunedda", "saints", "fl. 5th century", "Cunedda Wledig", "Cunedda Wledig", "Founder of Gwynedd", "Sylfaenydd Gwynedd", "Cunedda", "rulers",
   "The war leader who came south from Manaw Gododdin with his sons and founded the royal house of Gwynedd.",
   "Y rhyfelwr a ddaeth i’r de o Fanaw Gododdin gyda’i feibion a sefydlu tŷ brenhinol Gwynedd.",
   ["The Historia Brittonum tells that Cunedda came from Manaw Gododdin, the country around the head of the Firth of Forth, with eight of his sons, and drove the Irish out of north Wales.",
    "His sons and grandsons gave their names to the lands they won: Ceredig to Ceredigion, Meirion to Meirionnydd, Edern to Edeirnion, Dunod to Dunoding. From him came Maelgwn Gwynedd, Rhodri Mawr, Llywelyn the Great and every prince of Gwynedd to the last."],
   ["Mae’r Historia Brittonum yn adrodd i Gunedda ddod o Fanaw Gododdin, y wlad o gwmpas pen Moryd Forth, gydag wyth o’i feibion, a gyrru’r Gwyddelod o ogledd Cymru.",
    "Rhoddodd ei feibion a’i wyrion eu henwau i’r tiroedd a enillwyd ganddynt: Ceredig i Geredigion, Meirion i Feirionnydd, Edern i Edeirnion, Dunod i Ddunoding. Ohono ef y daeth Maelgwn Gwynedd, Rhodri Mawr, Llywelyn Fawr a phob tywysog Gwynedd hyd yr olaf."]),
 P("gildas", "saints", "c. 500–c. 570", "Gildas", "Gildas", "First historian of the Britons", "Hanesydd cyntaf y Brythoniaid", "Gildas", "learning",
   "Scholar of Llanilltud Fawr whose book On the Ruin of Britain is the only history written in Britain in the sixth century.",
   "Ysgolhaig o Lanilltud Fawr y mae ei lyfr Am Ddinistr Prydain yr unig hanes a ysgrifennwyd ym Mhrydain yn y chweched ganrif.",
   ["Gildas was a pupil of Illtud at Llanilltud Fawr, the great school of the Vale of Glamorgan. Around 540 he wrote De Excidio Britanniae, On the Ruin of Britain, a fiery sermon to the kings and clergy of his day that tells the story of the island since the Romans.",
    "It is the only account of those years written by someone who lived through them, and it names the victory of the Britons at Mount Badon. Gildas ended his days in Brittany, at Rhuys, where he is honoured as a founding saint."],
   ["Disgybl i Illtud yn Llanilltud Fawr, ysgol fawr Bro Morgannwg, oedd Gildas. Tua 540 ysgrifennodd De Excidio Britanniae, Am Ddinistr Prydain, pregeth danbaid i frenhinoedd a chlerigwyr ei ddydd sy’n adrodd hanes yr ynys ers y Rhufeiniaid.",
    "Dyma’r unig hanes am y blynyddoedd hynny gan un a fu fyw drwyddynt, ac mae’n enwi buddugoliaeth y Brythoniaid ym Mynydd Baddon. Diweddodd Gildas ei ddyddiau yn Llydaw, yn Rhuys, lle’i hanrhydeddir yn sant sylfaenol."],
   first=("world", "The first history of Britain written by a Briton", "Yr hanes cyntaf o Brydain gan Frython", 540)),
 P("urien-rheged", "saints", "fl. late 6th century", "Urien Rheged", "Urien Rheged", "Lord of the Old North", "Arglwydd yr Hen Ogledd", "Urien", "rulers",
   "King of Rheged in the Old North, praised by Taliesin as the greatest of the British kings who fought the Angles.",
   "Brenin Rheged yn yr Hen Ogledd, a folwyd gan Daliesin fel y mwyaf o frenhinoedd y Brythoniaid a ymladdodd yn erbyn yr Eingl.",
   ["Urien ruled Rheged, a Welsh-speaking kingdom around the Solway and Carlisle, in the second half of the sixth century. The Historia Brittonum says he led an alliance of British kings that besieged the Angles on the island of Lindisfarne for three days.",
    "Taliesin was his court poet, and the poems to Urien are among the oldest in Welsh, calling him the generous lord of Catraeth and the shield of his people. His son Owain ab Urien became a hero of Welsh story, the knight of the fountain."],
   ["Rheolai Urien Reged, teyrnas Gymraeg ei hiaith o gwmpas Solway a Chaerliwelydd, yn ail hanner y chweched ganrif. Dywed yr Historia Brittonum iddo arwain cynghrair o frenhinoedd y Brythoniaid a fu’n gwarchae ar yr Eingl ar ynys Metcaud am dri diwrnod.",
    "Taliesin oedd ei fardd llys, ac mae’r cerddi i Urien ymhlith y rhai hynaf yn y Gymraeg, yn ei alw’n arglwydd hael Catraeth a tharian ei bobl. Daeth ei fab Owain ab Urien yn arwr chwedlau Cymru, marchog y ffynnon."]),
 P("cadwallon", "saints", "d. 634", "Cadwallon ap Cadfan", "Cadwallon ap Cadfan", "King of Gwynedd", "Brenin Gwynedd", "Cadwallon_ap_Cadfan", "rulers",
   "King of Gwynedd who marched into the north of England and defeated and killed Edwin of Northumbria in 633.",
   "Brenin Gwynedd a orymdeithiodd i ogledd Lloegr a gorchfygu a lladd Edwin o Northumbria yn 633.",
   ["Driven from his kingdom by Edwin of Northumbria, Cadwallon is said to have taken refuge on Ynys Seiriol before returning to win it back. He made an alliance with Penda of Mercia and in 633 crushed Edwin at Hatfield Chase.",
    "For a year he held Northumbria, the only British king to rule so far into the land the Angles had taken. The poem Moliant Cadwallon praises his fourteen great battles and sixty encounters. He fell in 634, and his son Cadwaladr succeeded him."],
   ["Wedi i Edwin o Northumbria ei yrru o’i deyrnas, dywedir i Gadwallon gael lloches ar Ynys Seiriol cyn dychwelyd i’w hennill yn ôl. Gwnaeth gynghrair â Phenda o Fersia ac yn 633 trechodd Edwin yn Hatfield Chase.",
    "Am flwyddyn daliodd Northumbria, yr unig frenin Brythonig i reoli mor bell i’r tir a gymerwyd gan yr Eingl. Mae’r gerdd Moliant Cadwallon yn canmol ei bedair brwydr ar ddeg a’i drigain cyfranc. Syrthiodd yn 634, a’i fab Cadwaladr a’i olynodd."]),
 P("cadwaladr", "saints", "d. 682", "Cadwaladr Fendigaid", "Cadwaladr Fendigaid", "Cadwaladr the Blessed", "Cadwaladr Fendigaid", "Cadwaladr", "rulers",
   "King of Gwynedd remembered as the last high king of the Britons. Henry Tudor flew the red dragon of Cadwaladr at Bosworth.",
   "Brenin Gwynedd a gofir fel goruchaf frenin olaf y Brythoniaid. Chwifiodd Harri Tudur ddraig goch Cadwaladr ym Mosworth.",
   ["Cadwaladr ap Cadwallon ruled Gwynedd in the middle of the seventh century and was honoured as a saint, with churches named after him in Môn and Llŷn. Welsh tradition remembers him as the last of the British kings to claim the crown of the whole island.",
    "The poets prophesied that Cadwaladr would return and the Britons win back their land. In 1485 Henry Tudor, who traced his line to him, marched to Bosworth under a red dragon on a field of white and green, ‘the red dragon of Cadwaladr’. It is the dragon on the flag of Wales today."],
   ["Rheolai Cadwaladr ap Cadwallon Wynedd ganol y seithfed ganrif ac fe’i hanrhydeddwyd yn sant, ag eglwysi wedi’u henwi ar ei ôl ym Môn ac yn Llŷn. Mae traddodiad Cymru’n ei gofio fel yr olaf o frenhinoedd y Brythoniaid i hawlio coron yr ynys gyfan.",
    "Proffwydodd y beirdd y dychwelai Cadwaladr ac yr enillai’r Brythoniaid eu tir yn ôl. Yn 1485 gorymdeithiodd Harri Tudur, a olrheiniai ei linach ato, i Fosworth dan ddraig goch ar faes gwyn a gwyrdd, ‘draig goch Cadwaladr’. Hi yw’r ddraig ar faner Cymru heddiw."]),
 P("merfyn-frych", "kings", "d. 844", "Merfyn Frych", "Merfyn Frych", "King of Gwynedd", "Brenin Gwynedd", "Merfyn_Frych", "rulers",
   "King of Gwynedd from 825 whose court welcomed scholars from Ireland and who founded the dynasty of Rhodri Mawr.",
   "Brenin Gwynedd o 825 y croesawai ei lys ysgolheigion o Iwerddon, ac a sefydlodd linach Rhodri Mawr.",
   ["Merfyn Frych, Merfyn the Freckled, came to the throne of Gwynedd in 825. Welsh tradition holds that he came from the Isle of Man and that his line went back to Llywarch Hen and the kings of the Old North.",
    "His court was a place of learning. Irish scholars travelling to the Continent stopped there and left a puzzle, the Bamberg Cryptogram, set as a test for visitors to Merfyn’s court. The Historia Brittonum was written in his reign. His son Rhodri Mawr united much of Wales."],
   ["Daeth Merfyn Frych i orsedd Gwynedd yn 825. Yn ôl traddodiad Cymru daeth o Ynys Manaw, ac roedd ei linach yn mynd yn ôl at Lywarch Hen a brenhinoedd yr Hen Ogledd.",
    "Roedd ei lys yn lle dysg. Arhosai ysgolheigion o Iwerddon yno ar eu ffordd i’r Cyfandir, a gadawsant bos, Cryptogram Bamberg, yn brawf i ymwelwyr â llys Merfyn. Yn ei deyrnasiad ef yr ysgrifennwyd yr Historia Brittonum. Unodd ei fab Rhodri Mawr ran helaeth o Gymru."]),
 P("nennius", "kings", "fl. c. 829", "Nennius", "Nennius", "Historian of the Britons", "Hanesydd y Brythoniaid", "Nennius", "learning",
   "The Welsh monk named as compiler of the Historia Brittonum, the book that records Arthur’s twelve battles.",
   "Y mynach o Gymro a enwir yn gasglwr yr Historia Brittonum, y llyfr sy’n cofnodi deuddeg brwydr Arthur.",
   ["Around 829, in the reign of Merfyn Frych, a scholar in Gwynedd gathered together everything he could find about the past of the Britons: Roman histories, king lists, saints’ lives, genealogies and old wonders. Later copies name him as Nennius, a pupil of Elfoddw of Bangor.",
    "‘I have made a heap of all that I found,’ he wrote. His Historia Brittonum is the earliest source for the twelve battles of Arthur, for Vortigern and the coming of the Saxons, for Cunedda and for the boy Emrys and the two dragons at Dinas Emrys."],
   ["Tua 829, yn nheyrnasiad Merfyn Frych, casglodd ysgolhaig yng Ngwynedd y cyfan a allai ei gael am orffennol y Brythoniaid: hanesion Rhufeinig, rhestrau brenhinoedd, bucheddau saint, achau a hen ryfeddodau. Mae copïau diweddarach yn ei enwi’n Nennius, disgybl i Elfoddw o Fangor.",
    "‘Gwneuthum bentwr o’r cyfan a gefais,’ meddai. Ei Historia Brittonum yw’r ffynhonnell gynharaf am ddeuddeg brwydr Arthur, am Wrtheyrn a dyfodiad y Saeson, am Gunedda ac am y bachgen Emrys a’r ddwy ddraig yn Ninas Emrys."]),
 P("rhygyfarch", "kings", "1057–1099", "Rhygyfarch", "Rhygyfarch", "Biographer of Saint David", "Cofiannydd Dewi Sant", "Rhygyfarch", "learning",
   "Scholar of Llanbadarn Fawr who wrote the Life of Saint David, the book that made Dewi known across Christendom.",
   "Ysgolhaig o Lanbadarn Fawr a ysgrifennodd Fuchedd Dewi, y llyfr a wnaeth Dewi’n adnabyddus drwy’r byd Cristnogol.",
   ["Rhygyfarch was the eldest son of Sulien, twice bishop of St Davids, who ran a famous school at Llanbadarn Fawr. The family produced books, poems and illuminated manuscripts that are among the treasures of early Wales.",
    "Around 1090 Rhygyfarch wrote the Life of Saint David in Latin. It tells of Dewi’s birth to Non on the cliffs, of the hill rising beneath him at Llanddewi Brefi, and of his last words. It is the reason Dewi was made a saint for the whole Church and Wales has its patron saint. Rhygyfarch also wrote a lament for Wales under the Normans."],
   ["Rhygyfarch oedd mab hynaf Sulien, ddwywaith yn esgob Tyddewi, a gadwai ysgol enwog yn Llanbadarn Fawr. Cynhyrchodd y teulu lyfrau, cerddi a llawysgrifau addurnedig sydd ymhlith trysorau Cymru gynnar.",
    "Tua 1090 ysgrifennodd Rhygyfarch Fuchedd Dewi yn Lladin. Mae’n adrodd geni Dewi i Non ar y clogwyni, y bryn yn codi dano yn Llanddewi Brefi, a’i eiriau olaf. Dyna pam y gwnaed Dewi’n sant i’r Eglwys gyfan, a pham mae gan Gymru ei nawddsant. Ysgrifennodd Rhygyfarch hefyd alarnad dros Gymru dan y Normaniaid."]),
 P("rhys-ap-tewdwr", "kings", "d. 1093", "Rhys ap Tewdwr", "Rhys ap Tewdwr", "King of Deheubarth", "Brenin y Deheubarth", "Rhys_ap_Tewdwr", "rulers",
   "King of Deheubarth who held the south against the Normans. From him descend the Lord Rhys and, through his daughter Nest, many of the great families of Wales.",
   "Brenin y Deheubarth a ddaliodd y de yn erbyn y Normaniaid. Ohono ef y disgyn yr Arglwydd Rhys, a thrwy ei ferch Nest, llawer o deuluoedd mawr Cymru.",
   ["Rhys ap Tewdwr won the throne of Deheubarth in 1078 and with Gruffudd ap Cynan defeated his rivals at the battle of Mynydd Carn in 1081. That same year William the Conqueror came to St Davids, and the two kings made terms: Rhys kept his kingdom.",
    "For twelve years he held the south together while Norman lords pressed in from the border. He fell fighting near Brecon in 1093. His son Gruffudd and his grandson the Lord Rhys won Deheubarth back, and his daughter Nest became one of the most famous women in Welsh history."],
   ["Enillodd Rhys ap Tewdwr orsedd y Deheubarth yn 1078 a gyda Gruffudd ap Cynan trechodd ei wrthwynebwyr ym mrwydr Mynydd Carn yn 1081. Yr un flwyddyn daeth Gwilym Goncwerwr i Dyddewi, a daeth y ddau frenin i gytundeb: cadwodd Rhys ei deyrnas.",
    "Am ddeuddeng mlynedd daliodd y de ynghyd tra gwasgai arglwyddi Normanaidd o’r ffin. Syrthiodd yn ymladd ger Aberhonddu yn 1093. Enillodd ei fab Gruffudd a’i ŵyr yr Arglwydd Rhys y Deheubarth yn ôl, a daeth ei ferch Nest yn un o fenywod enwocaf hanes Cymru."]),
 P("geoffrey-of-monmouth", "medieval", "c. 1095–1155", "Geoffrey of Monmouth", "Sieffre o Fynwy", "Historian of the kings of Britain", "Hanesydd brenhinoedd Prydain", "Geoffrey_of_Monmouth", "words",
   "A man of Gwent whose History of the Kings of Britain carried Arthur, Merlin and King Lear to every court in Europe.",
   "Gŵr o Went y cariodd ei Hanes Brenhinoedd Prydain Arthur, Myrddin a’r Brenin Llŷr i bob llys yn Ewrop.",
   ["Geoffrey was born in or near Monmouth and taught at Oxford. Around 1136 he finished the Historia Regum Britanniae, the History of the Kings of Britain, which he said he had translated from ‘a very old book in the British tongue’.",
    "It tells the story of the Britons from Brutus of Troy to Cadwaladr, through Lear, Cymbeline, Vortigern, the prophecies of Myrddin and the reign of Arthur at Caerleon. It was one of the most read books of the Middle Ages, with over two hundred manuscripts surviving, and in Welsh as Brut y Brenhinedd it was treasured as the history of the nation. Shakespeare, Spenser and Tennyson all drew on it."],
   ["Ganed Sieffre yn Nhrefynwy neu gerllaw a bu’n athro yn Rhydychen. Tua 1136 gorffennodd yr Historia Regum Britanniae, Hanes Brenhinoedd Prydain, a ddywedai iddo ei gyfieithu o ‘hen lyfr yn iaith y Brythoniaid’.",
    "Mae’n adrodd hanes y Brythoniaid o Brutus o Gaerdroea hyd Gadwaladr, drwy Lŷr, Cynfelyn, Gwrtheyrn, proffwydoliaethau Myrddin a theyrnasiad Arthur yng Nghaerllion. Roedd yn un o lyfrau mwyaf poblogaidd yr Oesoedd Canol, ac mae dros ddau gant o lawysgrifau ohono wedi goroesi; yn Gymraeg, fel Brut y Brenhinedd, fe’i trysorwyd yn hanes y genedl. Tynnodd Shakespeare, Spenser a Tennyson arno."]),
 P("owain-cyfeiliog", "medieval", "c. 1130–1197", "Owain Cyfeiliog", "Owain Cyfeiliog", "Prince and poet of Powys", "Tywysog a bardd Powys", "Owain_Cyfeiliog", "rulers",
   "Prince of southern Powys and one of the finest poets of his age, author of Hirlas Owain, the drinking-horn poem.",
   "Tywysog de Powys ac un o feirdd gorau ei oes, awdur Hirlas Owain, cerdd y corn yfed.",
   ["Owain ap Gruffudd ap Maredudd ruled Cyfeiliog and the lands that took the name Powys Wenwynwyn after his son. He was praised by Gerald of Wales for his wit and eloquence.",
    "His poem Hirlas Owain is set on the night after a victory: the prince calls for the long blue drinking horn to be filled and carried to each of his warriors in turn, naming their deeds. It is one of the great poems of the Welsh princes. In old age he founded the abbey of Strata Marcella near Welshpool and retired there."],
   ["Rheolai Owain ap Gruffudd ap Maredudd Gyfeiliog a’r tiroedd a gymerodd yr enw Powys Wenwynwyn ar ôl ei fab. Canmolwyd ef gan Gerallt Gymro am ei ffraethineb a’i huodledd.",
    "Lleolir ei gerdd Hirlas Owain ar y noson wedi buddugoliaeth: mae’r tywysog yn galw am lenwi’r corn yfed hir glas a’i gludo i bob un o’i ryfelwyr yn ei dro, gan enwi eu campau. Mae’n un o gerddi mawr y tywysogion. Yn ei henaint sefydlodd abaty Ystrad Marchell ger y Trallwng ac ymddeol yno."]),
 P("hywel-ab-owain", "medieval", "d. 1170", "Hywel ab Owain Gwynedd", "Hywel ab Owain Gwynedd", "Warrior poet", "Y tywysog-fardd", "Hywel_ab_Owain_Gwynedd", "words",
   "Son of Owain Gwynedd, soldier and poet, whose poems of love and of the land of Gwynedd are among the most loved in Welsh.",
   "Mab Owain Gwynedd, milwr a bardd, y mae ei gerddi serch a’i gerddi i dir Gwynedd ymhlith y mwyaf annwyl yn y Gymraeg.",
   ["Hywel was the son of Owain Gwynedd and of Pyfog, an Irishwoman, and fought beside his father in the wars against the Normans and in Ceredigion.",
    "He was also a poet of rare freshness. In his Gorhoffedd, his Boast, he sings of the white-foaming sea, of the women he loved and of the hills and meadows of Meirionnydd: ‘I love its seaboard and its mountains’. He fell at Pentraeth in Môn in 1170, in the struggle for his father’s throne."],
   ["Mab Owain Gwynedd a Phyfog, Gwyddeles, oedd Hywel, ac ymladdodd gyda’i dad yn y rhyfeloedd yn erbyn y Normaniaid ac yng Ngheredigion.",
    "Roedd hefyd yn fardd o ffresni prin. Yn ei Orhoffedd mae’n canu am y môr gwyn ei ewyn, am y merched a garodd ac am fryniau a dolydd Meirionnydd: ‘Caraf ei morfa a’i mynyddedd’. Syrthiodd ym Mhentraeth ym Môn yn 1170, yn y frwydr am orsedd ei dad."]),
 P("madog", "medieval", "fl. 1170", "Madog ab Owain Gwynedd", "Madog ab Owain Gwynedd", "The prince who sailed west", "Y tywysog a hwyliodd tua’r gorllewin", "Madoc", "explore",
   "Son of Owain Gwynedd who, Welsh tradition holds, sailed west from Llandrillo in 1170 and reached America three centuries before Columbus.",
   "Mab Owain Gwynedd a hwyliodd, yn ôl traddodiad Cymru, tua’r gorllewin o Landrillo yn 1170 a chyrraedd America dair canrif cyn Columbus.",
   ["When Owain Gwynedd died in 1170, his sons fought over the kingdom. Welsh tradition holds that one of them, Madog, would have no part in the strife. He set sail from Llandrillo, near Rhos-on-Sea, in his ship Gwennan Gorn, went far to the west and found a new land. He came back for more settlers and sailed again, and did not return.",
    "The story was told in Wales for centuries and set down in print in the reign of Elizabeth I. In the eighteenth century travellers in America reported Welsh-speaking people on the Missouri, and in 1792 John Evans of Waunfawr set out to find them. A plaque at Fort Morgan in Mobile Bay, Alabama, set up in 1953, records that Madog landed there in 1170."],
   ["Pan fu farw Owain Gwynedd yn 1170, ymladdodd ei feibion am y deyrnas. Yn ôl traddodiad Cymru ni fynnai un ohonynt, Madog, ran yn y gynnen. Hwyliodd o Landrillo-yn-Rhos yn ei long Gwennan Gorn, aeth ymhell i’r gorllewin a chael gwlad newydd. Daeth yn ôl am ragor o ymsefydlwyr a hwylio eto, ac ni ddychwelodd.",
    "Adroddwyd y stori yng Nghymru am ganrifoedd a’i rhoi mewn print yn oes Elisabeth I. Yn y ddeunawfed ganrif dywedai teithwyr yn America fod pobl a siaradai Gymraeg ar afon Missouri, ac yn 1792 aeth John Evans o’r Waunfawr i chwilio amdanynt. Mae plac yn Fort Morgan ym Mae Mobile, Alabama, a godwyd yn 1953, yn cofnodi i Fadog lanio yno yn 1170."],
   first=("world", "Welsh tradition holds he reached America in 1170, over 300 years before Columbus", "Yn ôl traddodiad Cymru cyrhaeddodd America yn 1170, dros 300 mlynedd cyn Columbus", 1170)),
 P("dafydd-ap-llywelyn", "medieval", "c. 1212–1246", "Dafydd ap Llywelyn", "Dafydd ap Llywelyn", "The first Prince of Wales by title", "Y cyntaf i’w alw’n Dywysog Cymru", "Dafydd_ap_Llywelyn", "rulers",
   "Son of Llywelyn the Great and Joan, and the first ruler to call himself Prince of Wales, in 1244.",
   "Mab Llywelyn Fawr a Siwan, a’r rheolwr cyntaf i’w alw ei hun yn Dywysog Cymru, yn 1244.",
   ["Dafydd was the son of Llywelyn the Great and Joan, daughter of King John, and his father worked for years to make him sole heir to Gwynedd. He succeeded in 1240.",
    "In 1244 he became the first ruler to use the title princeps Wallie, Prince of Wales, and he asked the Pope to take Wales under his protection as a kingdom in its own right. He rallied the princes of Wales and won back much of what had been lost, but died young at Abergwyngregyn in 1246 and was buried beside his father at Aberconwy."],
   ["Mab Llywelyn Fawr a Siwan, merch y Brenin John, oedd Dafydd, a bu ei dad yn llafurio am flynyddoedd i’w wneud yn unig etifedd Gwynedd. Olynodd yn 1240.",
    "Yn 1244 ef oedd y rheolwr cyntaf i ddefnyddio’r teitl princeps Wallie, Tywysog Cymru, a gofynnodd i’r Pab gymryd Cymru dan ei nawdd fel teyrnas yn ei hawl ei hun. Cynullodd dywysogion Cymru ac ennill yn ôl lawer o’r hyn a gollwyd, ond bu farw’n ifanc yn Abergwyngregyn yn 1246 a’i gladdu wrth ochr ei dad yn Aberconwy."],
   first=("wales", "The first ruler to take the title Prince of Wales, in 1244", "Y rheolwr cyntaf i gymryd y teitl Tywysog Cymru, yn 1244", 1244)),
 P("dafydd-ap-gruffudd", "medieval", "c. 1238–1283", "Dafydd ap Gruffudd", "Dafydd ap Gruffudd", "The last prince", "Y tywysog olaf", "Dafydd_ap_Gruffydd", "rulers",
   "Brother of Llywelyn the Last, who began the final war in 1282 and led the Welsh after Llywelyn fell, the last independent Prince of Wales.",
   "Brawd Llywelyn ein Llyw Olaf, a ddechreuodd y rhyfel olaf yn 1282 ac a arweiniodd y Cymry wedi i Lywelyn syrthio, tywysog annibynnol olaf Cymru.",
   ["On Palm Sunday 1282 Dafydd ap Gruffudd stormed Hawarden Castle and set Wales alight. His brother Llywelyn joined the rising, and for the last time the princes of Wales fought together for their country.",
    "When Llywelyn was killed at Cilmeri in December, Dafydd took his place as Prince of Wales and fought on from the mountains of Eryri through the winter. He was taken in June 1283 at Bera Moel above Abergwyngregyn, betrayed by men of his own country, and put to death at Shrewsbury. He was the last native Prince of Wales."],
   ["Ar Sul y Blodau 1282 ymosododd Dafydd ap Gruffudd ar gastell Penarlâg a rhoi Cymru ar dân. Ymunodd ei frawd Llywelyn â’r gwrthryfel, ac am y tro olaf ymladdodd tywysogion Cymru gyda’i gilydd dros eu gwlad.",
    "Pan laddwyd Llywelyn yng Nghilmeri ym mis Rhagfyr, cymerodd Dafydd ei le yn Dywysog Cymru ac ymladd ymlaen o fynyddoedd Eryri drwy’r gaeaf. Fe’i daliwyd ym Mehefin 1283 ar Fera Moel uwchben Abergwyngregyn, wedi’i fradychu gan wŷr o’i wlad ei hun, a’i ddienyddio yn Amwythig. Ef oedd Tywysog Cymru brodorol olaf."]),
 P("gwenllian-ferch-llywelyn", "medieval", "1282–1337", "Gwenllian ferch Llywelyn", "Gwenllian ferch Llywelyn", "Princess of Wales", "Tywysoges Cymru", "Gwenllian_of_Wales", "rulers",
   "Only child of Llywelyn the Last, taken as a baby to a priory in Lincolnshire, where she lived her whole life. Wales remembers her as its lost princess.",
   "Unig blentyn Llywelyn ein Llyw Olaf, a gludwyd yn faban i briordy yn swydd Lincoln, lle bu fyw gydol ei hoes. Mae Cymru’n ei chofio’n dywysoges goll.",
   ["Gwenllian was born at Garth Celyn, Abergwyngregyn, in June 1282. Her mother, Eleanor de Montfort, died giving birth to her, and six months later her father fell at Cilmeri.",
    "Before she was two she was taken from Wales to the priory of Sempringham in Lincolnshire, so that no Welsh army could rally to her. She lived there for fifty-four years and died in 1337. A memorial stone was raised at Sempringham in 1993, and the peak of Carnedd Uchaf in Eryri was renamed Carnedd Gwenllian in her honour in 2009."],
   ["Ganed Gwenllian yng Ngarth Celyn, Abergwyngregyn, ym Mehefin 1282. Bu farw ei mam, Elinor de Montfort, wrth ei geni, a chwe mis yn ddiweddarach syrthiodd ei thad yng Nghilmeri.",
    "Cyn ei bod yn ddwyflwydd fe’i cludwyd o Gymru i briordy Sempringham yn swydd Lincoln, rhag i unrhyw fyddin Gymreig ymgynnull o’i chwmpas. Bu fyw yno am bedair blynedd ar ddeg a deugain, a bu farw yn 1337. Codwyd carreg goffa iddi yn Sempringham yn 1993, ac ailenwyd copa Carnedd Uchaf yn Eryri yn Garnedd Gwenllian er cof amdani yn 2009."]),
 P("llywelyn-bren", "medieval", "d. 1318", "Llywelyn Bren", "Llywelyn Bren", "Lord of Senghennydd", "Arglwydd Senghennydd", "Llywelyn_Bren", "rulers",
   "Welsh lord of Senghennydd who rose in 1316 for the people of Glamorgan, and gave himself up to save his followers.",
   "Arglwydd Cymreig Senghennydd a gododd yn 1316 dros bobl Morgannwg, ac a ildiodd er mwyn achub ei ddilynwyr.",
   ["Llywelyn ap Gruffudd, called Llywelyn Bren, was a cultured nobleman of the uplands of Glamorgan who owned books in Welsh, French and Latin. In a year of famine in 1316, with his people ground down by royal officials, he led them in a rising and besieged Caerphilly Castle.",
    "When the king’s armies came, he gave himself up on condition that his men be spared, saying it was better that one man die than a whole people. He was executed at Cardiff in 1318. Glamorgan has honoured him ever since as a hero of his people."],
   ["Uchelwr diwylliedig o ucheldir Morgannwg oedd Llywelyn ap Gruffudd, Llywelyn Bren, a feddai lyfrau yn Gymraeg, Ffrangeg a Lladin. Mewn blwyddyn o newyn yn 1316, a’i bobl wedi’u gwasgu gan swyddogion y brenin, arweiniodd hwy mewn gwrthryfel a gwarchae ar Gastell Caerffili.",
    "Pan ddaeth byddinoedd y brenin, ildiodd ar yr amod yr arbedid ei wŷr, gan ddweud ei bod yn well i un dyn farw na phobl gyfan. Fe’i dienyddiwyd yng Nghaerdydd yn 1318. Mae Morgannwg wedi’i anrhydeddu fyth ers hynny’n arwr ei bobl."]),
 P("iolo-goch", "medieval", "c. 1320–c. 1398", "Iolo Goch", "Iolo Goch", "Poet of Sycharth", "Bardd Sycharth", "Iolo_Goch", "words",
   "Master poet of the cywydd whose poem to Owain Glyndŵr’s home at Sycharth is the finest picture of a Welsh lord’s court.",
   "Prifardd y cywydd y mae ei gerdd i gartref Owain Glyndŵr yn Sycharth yn ddarlun gorau o lys uchelwr Cymreig.",
   ["Iolo Goch, from the Vale of Clwyd, was one of the first great masters of the cywydd, the form Dafydd ap Gwilym had made famous. He sang to kings and to ploughmen alike, and his poem in praise of the labourer is one of the first anywhere to honour the working man.",
    "His poem to Sycharth describes Owain Glyndŵr’s moated court in Powys: its nine halls, its tiled roof, its fishpond, deer park, mill and dovecote, and the open-handed welcome where ‘no hunger, no thirst’ was ever known. Without it we would hardly know what the home of a Welsh nobleman looked like."],
   ["Iolo Goch, o Ddyffryn Clwyd, oedd un o feistri mawr cyntaf y cywydd, y mesur a wnaeth Dafydd ap Gwilym yn enwog. Canai i frenhinoedd ac i lafurwyr fel ei gilydd, ac mae ei gywydd i’r llafurwr yn un o’r cyntaf yn unman i anrhydeddu’r gweithiwr.",
    "Mae ei gywydd i Sycharth yn disgrifio llys Owain Glyndŵr ym Mhowys a’i ffos o’i gwmpas: ei naw neuadd, ei do teils, ei bysgodlyn, ei barc ceirw, ei felin a’i golomendy, a’r croeso hael lle ‘nid oedd eisiau, na newyn’. Hebddo prin y gwyddem sut olwg oedd ar gartref uchelwr o Gymro."]),
 P("catrin-glyndwr", "medieval", "d. 1413", "Catrin Glyndŵr", "Catrin Glyndŵr", "Daughter of Owain", "Merch Owain", "Catrin_Glyndŵr", "rulers",
   "Daughter of Owain Glyndŵr, who shared the danger of her father’s war and died a prisoner in London. A memorial to her stands in the City of London.",
   "Merch Owain Glyndŵr, a rannodd berygl rhyfel ei thad ac a fu farw’n garcharor yn Llundain. Saif cofeb iddi yn Ninas Llundain.",
   ["Catrin was the daughter of Owain Glyndŵr and Margaret Hanmer. In 1402 she married Sir Edmund Mortimer, who had been captured by her father and then joined his cause, and the marriage sealed the great alliance that led to the Tripartite Indenture.",
    "When Harlech fell in 1409, Catrin, her children and her mother were taken to the Tower of London. She died in 1413 and was buried at St Swithin’s Church. In 2001 a memorial by Nic Hughes, with words by Menna Elfyn, was unveiled in St Swithin’s Church Garden, to her and to all women who suffer in war."],
   ["Merch Owain Glyndŵr a Margaret Hanmer oedd Catrin. Yn 1402 priododd Syr Edmund Mortimer, a ddaliwyd gan ei thad ac a ymunodd wedyn â’i achos, a seliodd y briodas y gynghrair fawr a arweiniodd at y Cytundeb Tridarn.",
    "Pan syrthiodd Harlech yn 1409, cludwyd Catrin, ei phlant a’i mam i Dŵr Llundain. Bu farw yn 1413 a’i chladdu yn Eglwys San Swithin. Yn 2001 dadorchuddiwyd cofeb gan Nic Hughes, gyda geiriau gan Menna Elfyn, yng Ngardd Eglwys San Swithin, iddi hi ac i bob menyw sy’n dioddef mewn rhyfel."]),
 P("owain-tudur", "medieval", "c. 1400–1461", "Owen Tudor", "Owain Tudur", "Grandfather of a king", "Taid brenin", "Owen_Tudor", "rulers",
   "A Welshman from Penmynydd in Môn who married the widowed queen of England and became grandfather of Henry VII.",
   "Cymro o Benmynydd ym Môn a briododd frenhines weddw Lloegr ac a ddaeth yn daid i Harri VII.",
   ["Owain ap Maredudd ap Tudur came of the Tudors of Penmynydd, a family that had served the princes of Gwynedd and stood with Owain Glyndŵr. He went into royal service and caught the eye of Catherine of Valois, widow of Henry V.",
    "They married secretly around 1430 and had several children, among them Edmund and Jasper Tudor. Owain fought for the house of Lancaster and was beheaded after the battle of Mortimer’s Cross in 1461. Twenty-four years later his grandson Henry Tudor took the crown at Bosworth, and the poets said a Welshman of Môn had come into his own."],
   ["Deuai Owain ap Maredudd ap Tudur o Duduriaid Penmynydd, teulu a fu’n gwasanaethu tywysogion Gwynedd ac a safodd gydag Owain Glyndŵr. Aeth i wasanaeth y brenin a dal llygad Catrin o Valois, gweddw Harri V.",
    "Priodasant yn ddirgel tua 1430 a chael sawl plentyn, yn eu plith Edmwnd a Siasbar Tudur. Ymladdodd Owain dros dŷ Lancaster a’i ddienyddio wedi brwydr Mortimer’s Cross yn 1461. Bedair blynedd ar hugain yn ddiweddarach cipiodd ei ŵyr Harri Tudur y goron ym Mosworth, a dywedodd y beirdd fod Cymro o Fôn wedi cael ei eiddo."]),
 P("jasper-tudor", "medieval", "c. 1431–1495", "Jasper Tudor", "Siasbar Tudur", "Earl of Pembroke", "Iarll Penfro", "Jasper_Tudor", "rulers",
   "Uncle and protector of Henry Tudor, who kept the boy safe through fourteen years of exile and brought him home to win the crown.",
   "Ewythr a gwarchodwr Harri Tudur, a gadwodd y bachgen yn ddiogel drwy bedair blynedd ar ddeg o alltudiaeth a’i ddwyn adref i ennill y goron.",
   ["Jasper was the son of Owain Tudur and Catherine of Valois. When his brother Edmund died in 1456, Jasper took in Edmund’s young widow, Margaret Beaufort, at Pembroke Castle, where she gave birth to Henry Tudor in January 1457.",
    "Through the Wars of the Roses Jasper never gave up the cause. In 1471 he escaped with the fourteen-year-old Henry from Tenby to Brittany, and for fourteen years guarded him in exile. In 1485 he landed with him at Mill Bay and rode beside him to Bosworth. He was made Duke of Bedford, and lies buried at Keynsham."],
   ["Mab Owain Tudur a Chatrin o Valois oedd Siasbar. Pan fu farw ei frawd Edmwnd yn 1456, rhoddodd Siasbar gartref i weddw ifanc Edmwnd, Margaret Beaufort, yng Nghastell Penfro, lle ganed Harri Tudur iddi yn Ionawr 1457.",
    "Drwy Ryfeloedd y Rhosynnau ni roddodd Siasbar y gorau i’r achos. Yn 1471 dihangodd gyda Harri, yn bedair ar ddeg oed, o Ddinbych-y-pysgod i Lydaw, a’i warchod mewn alltudiaeth am bedair blynedd ar ddeg. Yn 1485 glaniodd gydag ef ym Mae’r Felin a marchogaeth wrth ei ochr i Fosworth. Fe’i gwnaed yn Ddug Bedford, ac mae wedi’i gladdu yn Keynsham."]),
 P("lewys-glyn-cothi", "medieval", "c. 1420–1490", "Lewys Glyn Cothi", "Lewys Glyn Cothi", "Poet of the gentry", "Bardd yr uchelwyr", "Lewys_Glyn_Cothi", "words",
   "One of the great poets of the fifteenth century, who travelled all Wales singing to its families and wrote the most moving elegy in Welsh for his little son.",
   "Un o feirdd mawr y bymthegfed ganrif, a deithiodd Gymru gyfan yn canu i’w theuluoedd ac a ganodd y farwnad fwyaf ingol yn y Gymraeg i’w fab bach.",
   ["Lewys took his name from Glyn Cothi in Carmarthenshire. More of his poems survive than of any other medieval Welsh poet, many in his own handwriting, and they map the great houses of Wales from Anglesey to Gwent.",
    "He supported the house of Lancaster and the Tudors and sang of the hope of a Welsh king. His elegy for his five-year-old son Siôn y Glyn, in which he grieves that the boy’s ball and his marbles lie unused, is one of the tenderest poems in the language."],
   ["Cymerodd Lewys ei enw o Lyn Cothi yn Sir Gaerfyrddin. Mae mwy o’i gerddi ef wedi goroesi nag eiddo unrhyw fardd Cymraeg canoloesol arall, llawer yn ei lawysgrifen ei hun, ac maent yn fap o blasau mawr Cymru o Fôn i Went.",
    "Cefnogai dŷ Lancaster a’r Tuduriaid a chanodd am obaith brenin o Gymro. Mae ei farwnad i’w fab pumlwydd Siôn y Glyn, lle mae’n galaru fod pêl a marblis y bachgen yn segur, yn un o gerddi mwyaf tyner yr iaith."]),
 P("gwerful-mechain", "medieval", "fl. 1460–1502", "Gwerful Mechain", "Gwerful Mechain", "Poet of Powys", "Bardd o Bowys", "Gwerful_Mechain", "words",
   "The best known woman poet of medieval Wales: bold, funny and devout, she answered the male poets in their own strict metres.",
   "Bardd benywaidd enwocaf Cymru’r Oesoedd Canol: beiddgar, doniol a duwiol, atebodd y beirdd gwrywaidd yn eu mesurau caeth eu hunain.",
   ["Gwerful came from Mechain in Powys. More of her poems survive than of any other Welsh woman poet before modern times, and she mastered the strict-metre cywydd and englyn as well as any man of her day.",
    "She wrote religious poems on the Passion of Christ, poems of daily life, witty verse contests with Dafydd Llwyd of Mathafarn, and a famous reply to the poets who blamed women for the world’s troubles. Her frankness about love still startles readers five hundred years on."],
   ["O Fechain ym Mhowys y deuai Gwerful. Mae mwy o’i cherddi hi wedi goroesi nag eiddo unrhyw fardd benywaidd arall yng Nghymru cyn y cyfnod modern, a meistrolodd y cywydd a’r englyn caeth cystal ag unrhyw ddyn yn ei dydd.",
    "Ysgrifennodd gerddi crefyddol ar Ddioddefaint Crist, cerddi am fywyd bob dydd, ymrysonau ffraeth â Dafydd Llwyd o Fathafarn, ac ateb enwog i’r beirdd a feiai fenywod am drafferthion y byd. Mae ei gonestrwydd am gariad yn dal i synnu darllenwyr bum can mlynedd yn ddiweddarach."]),
 P("rhys-ap-thomas", "tudor", "1449–1525", "Sir Rhys ap Thomas", "Syr Rhys ap Thomas", "Kingmaker of Bosworth", "Gwneuthurwr brenin Bosworth", "Rhys_ap_Thomas", "rulers",
   "The greatest lord of south-west Wales, who brought his army to Henry Tudor in 1485 and was knighted on the field of Bosworth.",
   "Arglwydd mwyaf de-orllewin Cymru, a ddaeth â’i fyddin at Harri Tudur yn 1485 ac a urddwyd yn farchog ar faes Bosworth.",
   ["Rhys ap Thomas of Dinefwr and Carew was the most powerful man in south-west Wales. When Henry Tudor landed at Mill Bay in August 1485, Rhys raised his men and marched up through Wales to join him at Welshpool, his army the strongest part of Henry’s force.",
    "Welsh tradition holds that it was one of Rhys’s men who struck down Richard III. Henry knighted him on the field. He served the Tudors for forty years, ruled south Wales for the crown, and in 1507 held a great tournament at Carew Castle, the last of its kind in Britain."],
   ["Rhys ap Thomas o Ddinefwr a Chaeriw oedd y gŵr grymusaf yn ne-orllewin Cymru. Pan laniodd Harri Tudur ym Mae’r Felin yn Awst 1485, cododd Rhys ei wŷr a gorymdeithio i fyny drwy Gymru i ymuno ag ef yn y Trallwng, a’i fyddin ef oedd rhan gryfaf llu Harri.",
    "Yn ôl traddodiad Cymru, un o wŷr Rhys a drawodd Richard III i lawr. Urddodd Harri ef yn farchog ar y maes. Gwasanaethodd y Tuduriaid am ddeugain mlynedd, rheoli de Cymru dros y goron, ac yn 1507 cynnal twrnamaint mawr yng Nghastell Caeriw, yr olaf o’i fath ym Mhrydain."]),
 P("john-price", "tudor", "1502–1555", "Sir John Price", "Syr John Prys", "Printer of the first Welsh book", "Argraffydd y llyfr Cymraeg cyntaf", "John_Prise", "learning",
   "Scholar from Brecon who published the first book ever printed in Welsh, Yny lhyvyr hwnn, in 1546, and defended the history of the Britons.",
   "Ysgolhaig o Aberhonddu a gyhoeddodd y llyfr cyntaf erioed a argraffwyd yn Gymraeg, Yny lhyvyr hwnn, yn 1546, ac a amddiffynnodd hanes y Brythoniaid.",
   ["John Prys, of Brecon, was a lawyer and royal official who collected old Welsh manuscripts as the monasteries were closed and so saved many of them.",
    "In 1546 he published Yny lhyvyr hwnn, ‘In this book’, with the alphabet, the Creed, the Lord’s Prayer and the Ten Commandments in Welsh, so that people could learn their faith in their own tongue. It was the first book ever printed in Welsh. He also wrote a defence of the history of the Britons, and of Arthur, against the Italian scholar Polydore Vergil."],
   ["Cyfreithiwr a swyddog brenhinol o Aberhonddu oedd John Prys, a gasglodd hen lawysgrifau Cymraeg wrth i’r mynachlogydd gau ac felly achub llawer ohonynt.",
    "Yn 1546 cyhoeddodd Yny lhyvyr hwnn, gyda’r wyddor, y Credo, Gweddi’r Arglwydd a’r Deg Gorchymyn yn Gymraeg, er mwyn i bobl ddysgu eu ffydd yn eu hiaith eu hunain. Dyna’r llyfr cyntaf erioed a argraffwyd yn Gymraeg. Ysgrifennodd hefyd amddiffyniad o hanes y Brythoniaid, ac o Arthur, yn erbyn yr ysgolhaig Eidalaidd Polydore Vergil."],
   first=("wales", "The first book printed in Welsh, 1546", "Y llyfr cyntaf a argraffwyd yn Gymraeg, 1546", 1546)),
 P("william-salesbury", "tudor", "c. 1520–c. 1584", "William Salesbury", "William Salesbury", "Scholar of the Welsh New Testament", "Ysgolhaig y Testament Newydd Cymraeg", "William_Salesbury", "learning",
   "Scholar from Llansannan who made the first Welsh–English dictionary and translated the New Testament into Welsh in 1567.",
   "Ysgolhaig o Lansannan a luniodd y geiriadur Cymraeg–Saesneg cyntaf ac a gyfieithodd y Testament Newydd i’r Gymraeg yn 1567.",
   ["William Salesbury was one of the most learned Welshmen of his age. In 1547 he published A Dictionary in Englyshe and Welshe, the first of its kind, and he urged his countrymen to get the Scriptures in Welsh before the language was lost.",
    "When Parliament ordered a Welsh Bible in 1563, Salesbury did most of the work on the New Testament and the Book of Common Prayer, both published in 1567. His learned spelling made it hard going, but William Morgan built on it for the great Bible of 1588."],
   ["Roedd William Salesbury yn un o Gymry mwyaf dysgedig ei oes. Yn 1547 cyhoeddodd A Dictionary in Englyshe and Welshe, y cyntaf o’i fath, ac anogodd ei gyd-Gymry i gael yr Ysgrythurau yn Gymraeg cyn i’r iaith gael ei cholli.",
    "Pan orchmynnodd y Senedd Feibl Cymraeg yn 1563, Salesbury a wnaeth y rhan fwyaf o’r gwaith ar y Testament Newydd a’r Llyfr Gweddi Gyffredin, a gyhoeddwyd ill dau yn 1567. Roedd ei orgraff ddysgedig yn anodd, ond adeiladodd William Morgan arni ar gyfer Beibl mawr 1588."],
   first=("wales", "The first Welsh–English dictionary, 1547, and the first Welsh New Testament, 1567", "Y geiriadur Cymraeg–Saesneg cyntaf, 1547, a’r Testament Newydd Cymraeg cyntaf, 1567", 1547)),
 P("gruffydd-robert", "tudor", "c. 1527–c. 1598", "Gruffydd Robert", "Gruffydd Robert", "Grammarian in Milan", "Gramadegydd ym Milan", "Gruffydd_Robert", "learning",
   "Priest and scholar who, in exile in Italy, wrote the first printed grammar of Welsh, published in Milan in 1567.",
   "Offeiriad ac ysgolhaig a ysgrifennodd, yn alltud yn yr Eidal, y gramadeg Cymraeg printiedig cyntaf, a gyhoeddwyd ym Milan yn 1567.",
   ["Gruffydd Robert was archdeacon of Anglesey until the change of religion under Elizabeth I sent him abroad. He settled in Milan, where he served Cardinal Carlo Borromeo.",
    "Far from home, he wrote Dosparth Byrr ar y Rhann Gyntaf i Ramadeg Cymraeg, a grammar of Welsh set as a conversation between friends, printed in Milan in 1567. It was the first Welsh grammar ever printed, and in its preface he grieves that some Welsh people were ashamed of their language, and calls on them to love it."],
   ["Archddiacon Môn oedd Gruffydd Robert nes i’r newid crefydd dan Elisabeth I ei yrru dramor. Ymgartrefodd ym Milan, lle gwasanaethodd y Cardinal Carlo Borromeo.",
    "Ymhell o’i gartref ysgrifennodd Dosparth Byrr ar y Rhann Gyntaf i Ramadeg Cymraeg, gramadeg ar ffurf sgwrs rhwng cyfeillion, a argraffwyd ym Milan yn 1567. Dyna’r gramadeg Cymraeg cyntaf erioed mewn print, ac yn ei ragymadrodd mae’n gofidio fod rhai Cymry’n cywilyddio am eu hiaith, ac yn galw arnynt i’w charu."],
   first=("wales", "The first printed grammar of Welsh, Milan 1567", "Y gramadeg Cymraeg printiedig cyntaf, Milan 1567", 1567)),
 P("john-dee", "tudor", "1527–1609", "John Dee", "John Dee", "Mathematician to Elizabeth I", "Mathemategydd Elisabeth I", "John_Dee", "science",
   "Son of a Radnorshire family, mathematician and navigator to Elizabeth I, who first spoke of a ‘British Empire’ and claimed it through Madog.",
   "Mab i deulu o Faesyfed, mathemategydd a mordwywr i Elisabeth I, y cyntaf i sôn am ‘Ymerodraeth Brydeinig’, a’i hawlio drwy Fadog.",
   ["John Dee was born in London to a family from Nant-y-groes near Pilleth in Radnorshire, and was always proud of his Welsh descent from Rhodri Mawr. He became one of the most learned men in Europe, a mathematician, astronomer and geographer with the largest library in England.",
    "He taught navigation to the captains of Elizabeth I’s voyages of discovery and wrote the famous preface to the first English translation of Euclid. He coined the phrase ‘British Empire’, and argued that the queen had a right to lands in the west because Madog ab Owain Gwynedd had reached them first."],
   ["Ganed John Dee yn Llundain i deulu o Nant-y-groes ger Pilalau ym Maesyfed, ac roedd bob amser yn falch o’i dras Gymreig o Rodri Mawr. Daeth yn un o wŷr mwyaf dysgedig Ewrop, yn fathemategydd, seryddwr a daearyddwr a chanddo’r llyfrgell fwyaf yn Lloegr.",
    "Dysgodd fordwyo i gapteiniaid mordeithiau darganfod Elisabeth I ac ysgrifennu’r rhagair enwog i gyfieithiad Saesneg cyntaf Euclid. Bathodd yr ymadrodd ‘British Empire’, a dadlau fod gan y frenhines hawl i diroedd yn y gorllewin am mai Madog ab Owain Gwynedd a’u cyrhaeddodd gyntaf."]),
 P("twm-sion-cati", "tudor", "c. 1530–1609", "Twm Siôn Cati", "Twm Siôn Cati", "The Welsh Robin Hood", "Y Robin Hood Cymreig", "Twm_Siôn_Cati", "words",
   "Thomas Jones of Tregaron, poet and genealogist, remembered in Welsh tradition as the clever outlaw of the hills of Ceredigion.",
   "Thomas Jones o Dregaron, bardd ac achyddwr, a gofir yn nhraddodiad Cymru fel herwr cyfrwys bryniau Ceredigion.",
   ["Thomas Jones was born at Porth-y-ffynnon near Tregaron and became a respected herald and genealogist, drawing up the family trees of the gentry of Wales, and a poet.",
    "Folk memory made him something more: Twm Siôn Cati, the trickster of Ystrad Ffin who outwitted the rich and the sheriff’s men and hid in a cave on the hill of Dinas above the Tywi, still called Ogof Twm Siôn Cati. The tales were gathered into a novel in 1828 and are told to Welsh children still."],
   ["Ganed Thomas Jones ym Mhorth-y-ffynnon ger Tregaron a daeth yn herodr ac achyddwr uchel ei barch, yn llunio achau boneddigion Cymru, ac yn fardd.",
    "Gwnaeth cof gwerin ef yn fwy: Twm Siôn Cati, cnaf Ystrad Ffin a dwyllai’r cyfoethog a gwŷr y siryf ac a ymguddiai mewn ogof ar fryn Dinas uwchben y Tywi, a elwir yn Ogof Twm Siôn Cati o hyd. Casglwyd y straeon yn nofel yn 1828 ac fe’u hadroddir i blant Cymru o hyd."]),
 P("catrin-o-ferain", "tudor", "1534–1591", "Catrin of Berain", "Catrin o Ferain", "Mother of Wales", "Mam Cymru", "Katheryn_of_Berain", "rulers",
   "Heiress of Berain in Denbighshire, married four times, whose children and grandchildren filled the great houses of north Wales. She was called Mam Cymru.",
   "Aeres Berain yn Sir Ddinbych, a briododd bedair gwaith, ac y llanwodd ei phlant a’i hwyrion blasau mawr y gogledd. Fe’i gelwid yn Fam Cymru.",
   ["Catrin was heiress of Berain near Llannefydd, and Welsh tradition held that she was a great-granddaughter of Henry VII. She married four times, into the Salusburys, the Clough family, the Wynns of Gwydir and the Thelwalls, and through her many children she became ancestor of half the gentry of north Wales.",
    "Hence her name, Mam Cymru, the Mother of Wales. The poets sang her praises, and her portrait of 1568, attributed to Adriaen van Cronenburgh, hangs in the National Museum in Cardiff."],
   ["Aeres Berain ger Llannefydd oedd Catrin, ac yn ôl traddodiad roedd yn or-wyres i Harri VII. Priododd bedair gwaith, i deuluoedd y Salbriaid, y Cloughiaid, Wyniaid Gwydir a’r Thelwaliaid, a thrwy ei phlant lu daeth yn hynafiad i hanner boneddigion y gogledd.",
    "Dyna’i henw, Mam Cymru. Canodd y beirdd ei chlod, ac mae ei phortread o 1568, a briodolir i Adriaen van Cronenburgh, yn hongian yn yr Amgueddfa Genedlaethol yng Nghaerdydd."]),
 P("hugh-myddelton", "tudor", "1560–1631", "Sir Hugh Myddelton", "Syr Huw Myddelton", "Who brought water to London", "Y gŵr a ddaeth â dŵr i Lundain", "Hugh_Myddelton", "enterprise",
   "Goldsmith from Denbigh who built the New River, bringing clean water forty miles into London in 1613.",
   "Gof aur o Ddinbych a adeiladodd yr Afon Newydd, gan ddod â dŵr glân ddeugain milltir i Lundain yn 1613.",
   ["Hugh Myddelton was the sixth son of the governor of Denbigh Castle. He made his fortune as a goldsmith and merchant in London, and sat in Parliament for Denbigh.",
    "London was short of clean water, and in 1609 Myddelton took on a scheme everyone else had given up: a channel to bring spring water from Hertfordshire to Islington. The New River opened in 1613. It still supplies London today. Later he ran silver and lead mines in Cardiganshire, and his statue stands on Islington Green."],
   ["Chweched mab llywodraethwr Castell Dinbych oedd Huw Myddelton. Gwnaeth ei ffortiwn yn of aur ac yn fasnachwr yn Llundain, ac eisteddodd yn y Senedd dros Ddinbych.",
    "Roedd Llundain yn brin o ddŵr glân, ac yn 1609 ymgymerodd Myddelton â chynllun yr oedd pawb arall wedi rhoi’r gorau iddo: sianel i ddod â dŵr ffynnon o swydd Hertford i Islington. Agorwyd yr Afon Newydd yn 1613. Mae’n dal i gyflenwi Llundain heddiw. Yn ddiweddarach rheolodd fwyngloddiau arian a phlwm yng Ngheredigion, ac mae ei gerflun ar Islington Green."]),
 P("john-davies-mallwyd", "tudor", "c. 1567–1644", "John Davies of Mallwyd", "Dr John Davies, Mallwyd", "The greatest Welsh scholar", "Ysgolhaig mwyaf y Gymraeg", "John_Davies_(Mallwyd)", "learning",
   "Rector of Mallwyd who wrote the great Welsh grammar of 1621 and dictionary of 1632, and helped revise the Welsh Bible of 1620.",
   "Rheithor Mallwyd a ysgrifennodd ramadeg mawr 1621 a geiriadur 1632, ac a helpodd ddiwygio Beibl Cymraeg 1620.",
   ["John Davies was born in Llanferres in Denbighshire and worked with William Morgan on the Welsh Bible. As rector of Mallwyd in Meirionnydd for over forty years, he gave his life to the language.",
    "His Latin grammar of Welsh, Antiquae Linguae Britannicae Rudimenta, of 1621, and his great Welsh–Latin dictionary of 1632 set the standards of written Welsh for three hundred years. He also helped prepare the revised Bible of 1620 that the people of Wales read until the twentieth century."],
   ["Ganed John Davies yn Llanferres yn Sir Ddinbych a bu’n cydweithio â William Morgan ar y Beibl Cymraeg. Fel rheithor Mallwyd ym Meirionnydd am dros ddeugain mlynedd, rhoddodd ei fywyd i’r iaith.",
    "Gosododd ei ramadeg Lladin o’r Gymraeg, Antiquae Linguae Britannicae Rudimenta, 1621, a’i eiriadur mawr Cymraeg–Lladin, 1632, safonau’r Gymraeg ysgrifenedig am dri chan mlynedd. Helpodd hefyd i baratoi Beibl diwygiedig 1620 a ddarllenwyd gan bobl Cymru hyd yr ugeinfed ganrif."]),
 P("thomas-button", "tudor", "c. 1575–1634", "Sir Thomas Button", "Syr Thomas Button", "Explorer of Hudson Bay", "Fforiwr Bae Hudson", "Thomas_Button", "explore",
   "Sailor from St Lythans in the Vale of Glamorgan who led the 1612 voyage that explored the west of Hudson Bay, in search of the North-West Passage.",
   "Morwr o Sain Lythan ym Mro Morgannwg a arweiniodd fordaith 1612 a fforiodd orllewin Bae Hudson, yn chwilio am y Fynedfa Ogledd-orllewinol.",
   ["Thomas Button of Dyffryn, St Lythans, was a sea captain in the service of Henry, Prince of Wales. In 1612 he led two ships into Hudson Bay to find the passage to Asia and to search for Henry Hudson, who had been lost there.",
    "He sailed right across the bay, and his crews were the first Europeans to reach its western shore. They wintered at the mouth of a river he named the Nelson, and he charted the coast, naming it New Wales. He later became admiral of the king’s ships on the Irish coast."],
   ["Capten llong yng ngwasanaeth Harri, Tywysog Cymru, oedd Thomas Button o’r Dyffryn, Sain Lythan. Yn 1612 arweiniodd ddwy long i Fae Hudson i chwilio am y fynedfa i Asia ac am Henry Hudson, a gollwyd yno.",
    "Hwyliodd yn syth ar draws y bae, a’i griwiau ef oedd yr Ewropeaid cyntaf i gyrraedd ei lan orllewinol. Gaeafasant wrth aber afon a enwodd yn Nelson, a mapiodd yr arfordir, gan ei enwi’n New Wales. Daeth wedyn yn llyngesydd llongau’r brenin ar arfordir Iwerddon."],
   first=("world", "Led the first Europeans to reach the western shore of Hudson Bay, 1612", "Arweiniodd yr Ewropeaid cyntaf i gyrraedd glan orllewinol Bae Hudson, 1612", 1612)),
 P("george-herbert", "tudor", "1593–1633", "George Herbert", "George Herbert", "Poet of Montgomery", "Bardd Trefaldwyn", "George_Herbert", "words",
   "Born at Montgomery to the great Herbert family, one of the finest religious poets in the English language.",
   "Ganed yn Nhrefaldwyn i deulu mawr yr Herbertiaid; un o feirdd crefyddol gorau’r iaith Saesneg.",
   ["George Herbert was born in Montgomery in 1593, a son of the Welsh Herberts of Montgomery Castle, and his brother was the philosopher Lord Herbert of Chirbury. He was a brilliant scholar and public orator of Cambridge University.",
    "He gave up a career at court to become a country priest, and wrote the poems of The Temple, published after his early death in 1633. Hymns such as ‘Let all the world in every corner sing’ and ‘Teach me, my God and King’ are still sung everywhere."],
   ["Ganed George Herbert yn Nhrefaldwyn yn 1593, yn fab i Herbertiaid Cymreig Castell Trefaldwyn, ac roedd ei frawd yr athronydd yr Arglwydd Herbert o Chirbury. Roedd yn ysgolhaig disglair ac yn areithydd cyhoeddus Prifysgol Caergrawnt.",
    "Rhoddodd y gorau i yrfa yn y llys i fod yn offeiriad gwlad, ac ysgrifennu cerddi The Temple, a gyhoeddwyd wedi ei farw cynnar yn 1633. Cenir emynau fel ‘Let all the world in every corner sing’ ym mhobman o hyd."]),
 P("morgan-llwyd", "tudor", "1619–1659", "Morgan Llwyd", "Morgan Llwyd", "Mystic of Wrexham", "Cyfriniwr Wrecsam", "Morgan_Llwyd", "words",
   "Puritan preacher and writer from Cynfal in Meirionnydd whose Llyfr y Tri Aderyn is a classic of Welsh prose.",
   "Pregethwr Piwritanaidd ac awdur o Gynfal ym Meirionnydd y mae ei Lyfr y Tri Aderyn yn glasur o ryddiaith Gymraeg.",
   ["Morgan Llwyd was born at Cynfal Fawr near Maentwrog and became minister of the gathered church at Wrexham, one of the first Nonconformist congregations in Wales.",
    "His Llyfr y Tri Aderyn, the Book of the Three Birds, of 1653, is a conversation between the Eagle, the Raven and the Dove about the state of Britain and the soul. Its rich, musical Welsh made it one of the classics of the language, and the image of the inner light runs through all his writing."],
   ["Ganed Morgan Llwyd yng Nghynfal Fawr ger Maentwrog a daeth yn weinidog yr eglwys gynnull yn Wrecsam, un o’r cynulleidfaoedd Anghydffurfiol cyntaf yng Nghymru.",
    "Sgwrs rhwng yr Eryr, y Gigfran a’r Golomen am gyflwr Prydain a’r enaid yw ei Lyfr y Tri Aderyn, 1653. Gwnaeth ei Gymraeg gyfoethog, gerddorol ef yn un o glasuron yr iaith, ac mae delwedd y goleuni mewnol yn rhedeg drwy ei holl waith."]),
 P("henry-vaughan", "tudor", "1621–1695", "Henry Vaughan", "Henry Vaughan", "The Silurist", "Y Silwriad", "Henry_Vaughan", "words",
   "Poet and physician of Llansanffraid by the Usk, who called himself the Silurist after the ancient people of his country.",
   "Bardd a meddyg o Lansanffraid ar lan Wysg, a’i galwai ei hun yn Silwriad ar ôl hen bobl ei wlad.",
   ["Henry Vaughan spent most of his life at Newton in the parish of Llansanffraid, near Brecon, working as a doctor. He proudly signed himself ‘the Silurist’, after the Silures who had fought Rome in the land of his birth.",
    "His collection Silex Scintillans, of 1650 and 1655, is full of light, childhood and eternity: ‘I saw Eternity the other night, like a great ring of pure and endless light.’ He is buried at Llansanffraid, within sound of the river he loved."],
   ["Treuliodd Henry Vaughan y rhan fwyaf o’i oes yn Newton ym mhlwyf Llansanffraid, ger Aberhonddu, yn gweithio’n feddyg. Llofnodai ei hun yn falch yn ‘the Silurist’, ar ôl y Silwriaid a ymladdodd yn erbyn Rhufain yng ngwlad ei febyd.",
    "Mae ei gasgliad Silex Scintillans, 1650 a 1655, yn llawn goleuni, plentyndod a thragwyddoldeb: ‘Gwelais Dragwyddoldeb y noson o’r blaen, fel modrwy fawr o oleuni pur a diddiwedd.’ Mae wedi’i gladdu yn Llansanffraid, o fewn sŵn yr afon a garai."]),
 P("henry-morgan", "tudor", "c. 1635–1688", "Sir Henry Morgan", "Syr Harri Morgan", "Admiral of the Caribbean", "Llyngesydd y Caribî", "Henry_Morgan", "explore",
   "From Llanrhymni near Cardiff, the most famous captain of the Caribbean, who took Panama in 1671 and became governor of Jamaica.",
   "O Lanrhymni ger Caerdydd, capten enwocaf y Caribî, a gipiodd Panama yn 1671 ac a ddaeth yn llywodraethwr Jamaica.",
   ["Henry Morgan came from a gentry family of Llanrhymni, between Cardiff and Newport. He went to Jamaica as a young man and rose to command the privateers who defended the island for the English crown against Spain.",
    "His raids on Puerto Príncipe, Porto Bello and Maracaibo made his name, and in 1671 he crossed the Isthmus of Darién with over a thousand men and captured Panama, the richest city of the Spanish Main. He was knighted and made Lieutenant Governor of Jamaica, where he owned great estates. His name is still known the world over."],
   ["Deuai Harri Morgan o deulu bonheddig o Lanrhymni, rhwng Caerdydd a Chasnewydd. Aeth i Jamaica yn ŵr ifanc a chodi i arwain y preifatîriaid a amddiffynnai’r ynys dros goron Lloegr yn erbyn Sbaen.",
    "Gwnaeth ei gyrchoedd ar Puerto Príncipe, Porto Bello a Maracaibo ei enw, ac yn 1671 croesodd Gulfor Darién gyda dros fil o wŷr a chipio Panama, dinas gyfoethocaf y Main Sbaenaidd. Fe’i hurddwyd yn farchog a’i wneud yn Is-lywodraethwr Jamaica, lle bu’n berchen ar ystadau mawr. Mae ei enw’n hysbys drwy’r byd o hyd."]),
 P("elihu-yale", "tudor", "1649–1721", "Elihu Yale", "Elihu Yale", "Benefactor of Yale", "Noddwr Iâl", "Elihu_Yale", "enterprise",
   "Of the family of Plas yn Iâl near Llandegla, merchant and governor of Madras, whose gift founded the name of Yale University. He is buried at Wrexham.",
   "O deulu Plas yn Iâl ger Llandegla, masnachwr a llywodraethwr Madras, y rhoddodd ei rodd ei enw i Brifysgol Iâl. Mae wedi’i gladdu yn Wrecsam.",
   ["Elihu Yale’s family took its name from Iâl, the old commote of Yale in Denbighshire, where they held Plas yn Iâl. He was born in Boston, grew up in London and made his fortune with the East India Company, rising to be governor of Fort St George at Madras.",
    "In 1718 he sent books, a portrait of King George and goods worth £800 to the young Collegiate School of Connecticut, which gratefully renamed itself Yale College. It is now one of the great universities of the world. Yale is buried in the churchyard of St Giles, Wrexham, and his tomb carries the lines ‘Born in America, in Europe bred, in Africa travell’d and in Asia wed.’"],
   ["Cymerodd teulu Elihu Yale ei enw o Iâl, yr hen gwmwd yn Sir Ddinbych, lle daliasant Blas yn Iâl. Ganed ef yn Boston, fe’i magwyd yn Llundain a gwnaeth ei ffortiwn gyda Chwmni India’r Dwyrain, gan godi’n llywodraethwr Caer San Siôr ym Madras.",
    "Yn 1718 anfonodd lyfrau, portread o’r Brenin Siôr a nwyddau gwerth £800 i Ysgol Golegol ifanc Connecticut, a ailenwodd ei hun yn ddiolchgar yn Goleg Iâl. Mae’n awr yn un o brifysgolion mawr y byd. Mae Yale wedi’i gladdu ym mynwent San Silyn, Wrecsam, ac ar ei fedd mae’r llinellau ‘Born in America, in Europe bred, in Africa travell’d and in Asia wed.’"]),
 P("barti-ddu", "tudor", "1682–1722", "Bartholomew Roberts", "Barti Ddu", "The great sea rover", "Môr-leidr mwyaf y moroedd", "Bartholomew_Roberts", "explore",
   "John Roberts of Casnewydd Bach in Pembrokeshire, the most successful sea captain of the age of sail, who took over 400 ships.",
   "John Roberts o Gasnewydd Bach yn Sir Benfro, capten llong mwyaf llwyddiannus oes yr hwyliau, a gipiodd dros 400 o longau.",
   ["John Roberts was born at Casnewydd Bach near Fishguard and went to sea as a boy. In 1719 his ship was taken by the Welsh captain Hywel Davies off the coast of Africa, and when Davies was killed weeks later the crew chose the newcomer as their captain. He took the name Bartholomew, and the Welsh have called him Barti Ddu ever since.",
    "In under three years he took more than four hundred ships from Newfoundland to Brazil and West Africa, more than any captain of his time. He was a strict leader who drank only tea and set down written articles that his crew agreed to. He fell in battle off Cape Lopez in 1722, dressed in crimson with a gold chain, and his men buried him at sea as he had asked. I. D. Hooson’s poem keeps his name alive in Wales."],
   ["Ganed John Roberts yng Nghasnewydd Bach ger Abergwaun ac aeth i’r môr yn fachgen. Yn 1719 cipiwyd ei long gan y capten Cymreig Hywel Davies oddi ar arfordir Affrica, a phan laddwyd Davies wythnosau wedyn dewisodd y criw y newydd-ddyfodiad yn gapten. Cymerodd yr enw Bartholomew, ac mae’r Cymry wedi’i alw’n Farti Ddu fyth ers hynny.",
    "Mewn llai na thair blynedd cipiodd dros bedwar cant o longau o Newfoundland i Frasil a Gorllewin Affrica, mwy nag unrhyw gapten yn ei oes. Roedd yn arweinydd llym a yfai de yn unig ac a osododd erthyglau ysgrifenedig y cytunodd ei griw iddynt. Syrthiodd mewn brwydr oddi ar Cape Lopez yn 1722, wedi’i wisgo mewn rhuddgoch gyda chadwyn aur, a chladdodd ei wŷr ef yn y môr fel y gofynasai. Mae cerdd I. D. Hooson yn cadw’i enw’n fyw yng Nghymru."],
   first=("world", "The most successful sea captain of the age of sail: over 400 ships taken", "Capten mwyaf llwyddiannus oes yr hwyliau: dros 400 o longau", 1722)),
]
